   558→void co_resume( stCoRoutine_t *co )
   559→{
   560→	stCoRoutineEnv_t *env = co->env;
   561→	stCoRoutine_t *lpCurrRoutine = env->pCallStack[ env->iCallStackSize - 1 ];
   562→	if( !co->cStart )
   563→	{
   564→		coctx_make( &co->ctx,(coctx_pfn_t)CoRoutineFunc,co,0 );
   565→		co->cStart = 1;
   566→	}
   567→	env->pCallStack[ env->iCallStackSize++ ] = co;
   568→	co_swap( lpCurrRoutine, co );
   569→
   570→
   571→}
