   597→void co_yield_env( stCoRoutineEnv_t *env )
   598→{
   599→	
   600→	stCoRoutine_t *last = env->pCallStack[ env->iCallStackSize - 2 ];
   601→	stCoRoutine_t *curr = env->pCallStack[ env->iCallStackSize - 1 ];
   602→
   603→	env->iCallStackSize--;
   604→
   605→	co_swap( curr, last);
   606→}
