   618→void save_stack_buffer(stCoRoutine_t* occupy_co)
   619→{
   620→	///copy out
   621→	stStackMem_t* stack_mem = occupy_co->stack_mem;
   622→	int len = stack_mem->stack_bp - occupy_co->stack_sp;
   623→
   624→	if (occupy_co->save_buffer)
   625→	{
   626→		free(occupy_co->save_buffer), occupy_co->save_buffer = NULL;
   627→	}
   628→
   629→	occupy_co->save_buffer = (char*)malloc(len); //malloc buf;
   630→	occupy_co->save_size = len;
   631→
   632→	memcpy(occupy_co->save_buffer, occupy_co->stack_sp, len);
   633→}
   634→
   635→void co_swap(stCoRoutine_t* curr, stCoRoutine_t* pending_co)
   636→{
   637→ 	stCoRoutineEnv_t* env = co_get_curr_thread_env();
   638→
   639→	//get curr stack sp
   640→	char c;
   641→	curr->stack_sp= &c;
   642→
   643→	if (!pending_co->cIsShareStack)
   644→	{
   645→		env->pending_co = NULL;
   646→		env->occupy_co = NULL;
   647→	}
   648→	else 
   649→	{
   650→		env->pending_co = pending_co;
   651→		//get last occupy co on the same stack mem
   652→		stCoRoutine_t* occupy_co = pending_co->stack_mem->occupy_co;
   653→		//set pending co to occupy thest stack mem;
   654→		pending_co->stack_mem->occupy_co = pending_co;
   655→
   656→		env->occupy_co = occupy_co;
   657→		if (occupy_co && occupy_co != pending_co)
   658→		{
   659→			save_stack_buffer(occupy_co);
   660→		}
   661→	}
   662→
   663→	//swap context
   664→	coctx_swap(&(curr->ctx),&(pending_co->ctx) );
   665→
   666→	//stack buffer may be overwrite, so get again;
   667→	stCoRoutineEnv_t* curr_env = co_get_curr_thread_env();
   668→	stCoRoutine_t* update_occupy_co =  curr_env->occupy_co;
   669→	stCoRoutine_t* update_pending_co = curr_env->pending_co;
   670→	
   671→	if (update_occupy_co && update_pending_co && update_occupy_co != update_pending_co)
   672→	{
   673→		//resume stack buffer
   674→		if (update_pending_co->save_buffer && update_pending_co->save_size > 0)
   675→		{
   676→			memcpy(update_pending_co->stack_sp, update_pending_co->save_buffer, update_pending_co->save_size);
   677→		}
   678→	}
   679→}
