   772→void OnPollPreparePfn( stTimeoutItem_t * ap,struct epoll_event &e,stTimeoutItemLink_t *active )
   773→{
   774→	stPollItem_t *lp = (stPollItem_t *)ap;
   775→	lp->pSelf->revents = EpollEvent2Poll( e.events );
   776→
   777→
   778→	stPoll_t *pPoll = lp->pPoll;
   779→	pPoll->iRaiseCnt++;
   780→
   781→	if( !pPoll->iAllEventDetach )
   782→	{
   783→		pPoll->iAllEventDetach = 1;
   784→
   785→		RemoveFromLink<stTimeoutItem_t,stTimeoutItemLink_t>( pPoll );
   786→
   787→		AddTail( active,pPoll );
   788→
   789→	}
   790→}
