   793→void co_eventloop( stCoEpoll_t *ctx,pfn_co_eventloop_t pfn,void *arg )
   794→{
   795→	if( !ctx->result )
   796→	{
   797→		ctx->result =  co_epoll_res_alloc( stCoEpoll_t::_EPOLL_SIZE );
   798→	}
   799→	co_epoll_res *result = ctx->result;
   800→
   801→
   802→	for(;;)
   803→	{
   804→		int ret = co_epoll_wait( ctx->iEpollFd,result,stCoEpoll_t::_EPOLL_SIZE, 1 );
   805→
   806→		stTimeoutItemLink_t *active = (ctx->pstActiveList);
   807→		stTimeoutItemLink_t *timeout = (ctx->pstTimeoutList);
   808→
   809→		memset( timeout,0,sizeof(stTimeoutItemLink_t) );
   810→
   811→		for(int i=0;i<ret;i++)
   812→		{
   813→			stTimeoutItem_t *item = (stTimeoutItem_t*)result->events[i].data.ptr;
   814→			if( item->pfnPrepare )
   815→			{
   816→				item->pfnPrepare( item,result->events[i],active );
   817→			}
   818→			else
   819→			{
   820→				AddTail( active,item );
   821→			}
   822→		}
   823→
   824→
   825→		unsigned long long now = GetTickMS();
   826→		TakeAllTimeout( ctx->pTimeout,now,timeout );
   827→
   828→		stTimeoutItem_t *lp = timeout->head;
   829→		while( lp )
   830→		{
   831→			//printf("raise timeout %p\n",lp);
   832→			lp->bTimeout = true;
   833→			lp = lp->pNext;
   834→		}
   835→
   836→		Join<stTimeoutItem_t,stTimeoutItemLink_t>( active,timeout );
   837→
   838→		lp = active->head;
   839→		while( lp )
   840→		{
   841→
   842→			PopHead<stTimeoutItem_t,stTimeoutItemLink_t>( active );
   843→            if (lp->bTimeout && now < lp->ullExpireTime) 
   844→			{
   845→				int ret = AddTimeout(ctx->pTimeout, lp, now);
   846→				if (!ret) 
   847→				{
   848→					lp->bTimeout = false;
   849→					lp = active->head;
   850→					continue;
   851→				}
   852→			}
   853→			if( lp->pfnProcess )
   854→			{
   855→				lp->pfnProcess( lp );
   856→			}
   857→
   858→			lp = active->head;
   859→		}
   860→		if( pfn )
   861→		{
   862→			if( -1 == pfn( arg ) )
   863→			{
   864→				break;
   865→			}
   866→		}
   867→
   868→	}
   869→}
